public class MedianOfTwoSortedArrays { public static double FindMedianSortedArrays(int[] nums1, int[] nums2) { int[] merged = new int[nums1.Length + nums2.Length]; int i = 0, j = 0, k = 0; while (i < nums1.Length && j < nums2.Length) { if (nums1[i] < nums2[j]) { merged[k++] = nums1[i++]; } else { merged[k++] = nums2[j++]; } } while (i < nums1.Length) { merged[k++] = nums1[i++]; } while (j < nums2.Length) { merged[k++] = nums2[j++]; } int length = merged.Length; if (length % 2 == 0) { return (merged[length / 2 - 1] + merged[length / 2]) / 2.0; } else { return merged[length / 2]; } } }